param(
  [Parameter(Mandatory=$true)][string]$OutputPath
)

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Drawing

# Canonical Lex Machina artwork supplied for the Windows application/installer icon.
# The source is stored as a compact 256x256 JPEG and converted deterministically
# into a multi-resolution ICO on every Windows installer build.
$SourceJpegBase64 = @'

'@

$sourceBytes = [Convert]::FromBase64String($SourceJpegBase64)
$sourceStream = New-Object IO.MemoryStream(,$sourceBytes)
$sourceImage = [Drawing.Image]::FromStream($sourceStream)
$sizes = @(16,20,24,32,40,48,64,128,256)
$frames = New-Object 'System.Collections.Generic.List[byte[]]'

try {
  foreach ($size in $sizes) {
    $bitmap = New-Object Drawing.Bitmap($size, $size, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $graphics = [Drawing.Graphics]::FromImage($bitmap)
    $pngStream = New-Object IO.MemoryStream
    try {
      $graphics.CompositingMode = [Drawing.Drawing2D.CompositingMode]::SourceCopy
      $graphics.CompositingQuality = [Drawing.Drawing2D.CompositingQuality]::HighQuality
      $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
      $graphics.SmoothingMode = [Drawing.Drawing2D.SmoothingMode]::HighQuality
      $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
      $graphics.DrawImage($sourceImage, 0, 0, $size, $size)
      $bitmap.Save($pngStream, [Drawing.Imaging.ImageFormat]::Png)
      $frames.Add($pngStream.ToArray())
    } finally {
      $pngStream.Dispose()
      $graphics.Dispose()
      $bitmap.Dispose()
    }
  }
} finally {
  $sourceImage.Dispose()
  $sourceStream.Dispose()
}

$output = [IO.Path]::GetFullPath($OutputPath)
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $output) | Out-Null
$stream = [IO.File]::Open($output, [IO.FileMode]::Create, [IO.FileAccess]::Write, [IO.FileShare]::None)
$writer = New-Object IO.BinaryWriter($stream)
try {
  $writer.Write([uint16]0) # reserved
  $writer.Write([uint16]1) # ICO
  $writer.Write([uint16]$sizes.Count)
  $offset = 6 + (16 * $sizes.Count)
  for ($i = 0; $i -lt $sizes.Count; $i++) {
    $size = $sizes[$i]
    $frame = $frames[$i]
    $writer.Write([byte]($(if ($size -eq 256) { 0 } else { $size })))
    $writer.Write([byte]($(if ($size -eq 256) { 0 } else { $size })))
    $writer.Write([byte]0) # palette
    $writer.Write([byte]0) # reserved
    $writer.Write([uint16]1)
    $writer.Write([uint16]32)
    $writer.Write([uint32]$frame.Length)
    $writer.Write([uint32]$offset)
    $offset += $frame.Length
  }
  foreach ($frame in $frames) { $writer.Write($frame) }
  $writer.Flush()
} finally {
  $writer.Dispose()
  $stream.Dispose()
}

$bytes = [IO.File]::ReadAllBytes($output)
if ($bytes.Length -lt 1024 -or $bytes[0] -ne 0 -or $bytes[1] -ne 0 -or $bytes[2] -ne 1 -or $bytes[3] -ne 0) {
  throw "WINDOWS_ICON_INVALID:$output"
}
$hash = (Get-FileHash -Algorithm SHA256 -LiteralPath $output).Hash.ToLowerInvariant()
Write-Host "WINDOWS_ICON_READY:$output"
Write-Host "WINDOWS_ICON_FRAMES=$($sizes -join ',')"
Write-Host "WINDOWS_ICON_SHA256=$hash"
